theme.css:
/* Story by HTML5 UP | html5up.net | @ajlkn | CC BY 3.0.
 * Adapted for ImmichPager; composition, typography and accessibility modified. */
.ip-hero { max-width:1280px; padding:32px; }
.ip-hero .ip-header { padding:clamp(28px, 1.5rem + 2vw, 56px); }
.ip-hero .ip-banner { border-radius:2px; }
.ip-title { font-weight:var(--pager-title-font-weight); letter-spacing:-.025em; line-height:1.12; }
.ip-description { max-width:36em; line-height:1.7; }
.ip-hero .ip-navigation { padding:20px 32px; border-top:1px solid var(--pager-border); }
.ip-block { padding-block:40px; }
@media(max-width:760px) { .ip-hero { padding:0; } .ip-hero .ip-header { padding:32px 24px; } .ip-hero .ip-banner { height:360px; max-height:none; } .ip-hero .ip-navigation { padding:20px 24px; } }

.ip-description { opacity:1; }
.ip-albums:not(.tiles) .ip-album-info p { opacity:1; color:var(--pager-muted); }
.ip-albums.tiles .ip-album-info p { opacity:1; color:#ffffff; }
